SELECT COUNT(*) AS cancelled_orders_count
FROM orders
WHERE status = 'cancelled';

SELECT COUNT(*) AS total_mall_shops
FROM sellers
WHERE is_mall = TRUE;

SELECT COUNT(*) AS total_percent_vouchers
FROM vouchers
WHERE discount_type = 'percent';

SELECT COUNT(*) AS total_root_categories
FROM categories
WHERE parent_id IS NULL;

SELECT COUNT(*) AS total_five_star_reviews
FROM reviews
WHERE rating = 5;

SELECT 
    COUNT(CASE WHEN status = 'returned' THEN 1 END) * 100.0 / COUNT(*) AS return_rate
FROM orders;
